BEGIN READ ONLY; SET LOCAL statement_timeout='10s'; SELECT json_build_object('kind','writeLease','key',lease_key,'acquiredAt',acquired_at,'expiresAt',expires_at,'notExpired',expires_at>clock_timestamp()) FROM production_write_leases; SELECT json_build_object('kind','financialCursorProgress','total',count(*),'latestAttempt',max(last_attempted_at),'attemptsSinceRunStart',count(*) FILTER(WHERE last_attempted_at>'2026-10-11T12:42:46Z')) FROM candidate_financial_acquisition_cursors_v4; SELECT json_build_object('kind','run','pipelineStatus',p.status,'researchStatus',r.status,'items',(SELECT count(*) FROM candidate_research_run_items i WHERE i.run_id=r.id)) FROM pipeline_runs p JOIN candidate_research_runs r ON r.pipeline_run_id=p.id WHERE p.id='918db413-a56c-4cd6-86f8-617b4a6b1239' AND r.id='d500fa84-e57b-4c3d-bafd-deac37ebf249'; ROLLBACK;
